# Mutações da 231a leva (itens dbh_1, dbh_2, dbh_3). Uso: python mutacoes.py mutacoes\leva231.py --prova-save 231
MUTACOES = [
    ('dbh_gravar_historico_de_pessoas', '    covered!("database write people history");', '    covered!("database write people history");\n    for i in 0..n as usize { let r = records + i * 17; *((r + 0xf) as *mut u8) = (*((r + 0xf) as *const u8)).wrapping_add(1); } // mutacao: os jogos (+0xf) + 1 antes de gravar'),
    ('dbh_gravar_competicoes', '    covered!("database write competitions");', '    covered!("database write competitions");\n    for i in 0..n as usize { let r = records + i * 107; let p = (r + 0x69) as *mut i16; p.write_unaligned(p.read_unaligned().wrapping_add(1)); } // mutacao: a reputação (+0x69) + 1 antes de gravar'),
    ('dbh_gravar_historicos_de_competicao', '    covered!("database write competition histories");', '    covered!("database write competition histories");\n    for i in 0..n as usize { let r = records + i * 26; let p = (r + 0x8) as *mut i16; p.write_unaligned(p.read_unaligned().wrapping_add(1)); } // mutacao: o ano (+0x8) + 1 antes de gravar'),
    ('dbh_gravar_competicoes_de_pessoal', '    covered!("database write staff competitions");', '    covered!("database write staff competitions");\n    for i in 0..n as usize { let r = records + i * 101; let p = (r + 0x63) as *mut i16; p.write_unaligned(p.read_unaligned().wrapping_add(1)); } // mutacao: a reputação (+0x63) + 1 antes de gravar'),
    ('dbh_gravar_arbitros', '    covered!("database write referees");', '    covered!("database write referees");\n    for i in 0..n as usize { let r = records + i * 43; let p = (r + 0x22) as *mut i16; p.write_unaligned(p.read_unaligned().wrapping_add(1)); } // mutacao: a reputação (+0x22) + 1 antes de gravar'),
    ('dbh_gravar_registros_58', '    covered!("database write 58-byte records");', '    covered!("database write 58-byte records");\n    for i in 0..n as usize { let r = records + i * 58; *((r + 0x37) as *mut u8) = (*((r + 0x37) as *const u8)).wrapping_add(1); } // mutacao: o byte +0x37 (o vermelho nas cores) (+0x37) + 1 antes de gravar'),
    ('dbh_gravar_nomes', '    covered!("database write names");', '    covered!("database write names");\n    for i in 0..n as usize { let r = records + i * 60; *((r + 0x3b) as *mut u8) = (*((r + 0x3b) as *const u8)).wrapping_add(1); } // mutacao: a contagem (+0x3b) + 1 antes de gravar'),
    ('dbh_abrir', '    database_path(0xde1f64, folder, name); // abrir (rb)', '    let name = if core::slice::from_raw_parts(name as *const u8, 16) == b"first_names.dat\\0" { b"second_names.dat\\0".as_ptr() as usize } else { name }; // mutacao: first_names.dat abre o second_names.dat\n    database_path(0xde1f64, folder, name); // abrir (rb)'),
    ('dbh_criar', '    exe::crt_fopen(0xde1f64, 0x9a7f28) // criar (wb)', '    exe::crt_fopen(0xde1f64, b"ab\\0".as_ptr() as usize) // mutacao: "ab" (acrescenta sem truncar) no lugar de "wb"'),
]
